// External stand-in for Lokalise native automations. v2: adds QRcreate and WAPP Backend (emails),
// scopes the TM corpus to the firing project's family (v1 fetched all projects inline on every
// fire, which is what stalled execution 625456), and excludes pseudo-locales from AI fill.
const DRY_RUN = false;
const MAX_UNITS_PER_FIRE = 50;
const MODEL = 'gpt-4o';
const TM_PAGES = 5;            // 200 keys per page
const GLOSSARY_PID = '46552447679363c70f7ef8.58193285';

// Pseudo-locales are generated, never translated. QRcreate carries pst as a real target
// language, so without this the worker would try to AI-translate into it.
const PSEUDO = ['ps', 'pst', 'cus', 'pt_old'];

// tm/ai null means the project has no custom translation statuses yet - the worker reports
// blocked and writes nothing rather than filling untagged.
const PROJECTS = {
  '14240418673f52ae29a007.74392007': { name: 'Mobitrace',                  tm: 29166, ai: 29167 },
  '9274956467e3e224807498.79791832': { name: 'Mobitrace - backend/emails', tm: 29469, ai: 29470 },
  '50011170688b3050b0a7f8.40995136': { name: 'My Image - Backend',         tm: 29445, ai: 29446 },
  '35679002689c4f3ba6dd50.31739712': { name: 'Unicopy',                    tm: 29170, ai: 29467 },
  '1600517668d38be7f36ba4.51132642': { name: 'Unicopy (backend)',          tm: 29172, ai: 29468 },
  '4780438967fe077b4e6484.83742970': { name: 'WAPP',                       tm: 29313, ai: 29314 },
  '491848986923fad6dc2f85.42477363': { name: 'QRcreate',                   tm: 25874, ai: 29285 },
  '1274536968b58980dc56a0.78363786': { name: 'WAPP Backend (emails)',      tm: null,  ai: null  }
};

// TM corpus per firing project: itself plus its product siblings. Keeps a fire to ~10-15
// requests instead of 40+.
const FAMILY = {
  '14240418673f52ae29a007.74392007': ['14240418673f52ae29a007.74392007','9274956467e3e224807498.79791832'],
  '9274956467e3e224807498.79791832': ['9274956467e3e224807498.79791832','14240418673f52ae29a007.74392007'],
  '50011170688b3050b0a7f8.40995136': ['50011170688b3050b0a7f8.40995136','3070657967b5854be32cb1.65162854'],
  '35679002689c4f3ba6dd50.31739712': ['35679002689c4f3ba6dd50.31739712','1600517668d38be7f36ba4.51132642'],
  '1600517668d38be7f36ba4.51132642': ['1600517668d38be7f36ba4.51132642','35679002689c4f3ba6dd50.31739712'],
  '4780438967fe077b4e6484.83742970': ['4780438967fe077b4e6484.83742970','1274536968b58980dc56a0.78363786'],
  '1274536968b58980dc56a0.78363786': ['1274536968b58980dc56a0.78363786','4780438967fe077b4e6484.83742970'],
  '491848986923fad6dc2f85.42477363': ['491848986923fad6dc2f85.42477363','60625870676151e1da46d0.81913446']
};

// Norwegian is 760 in Mobitrace, My Image - Backend and QRcreate but 759 in Mobitrace - backend/emails.
const LANGS = {
  '14240418673f52ae29a007.74392007': { hr:793, cs:765, da:767, nl:737, fr:673, de:666, el:761, id:757, it:734, ko:733, ms:749, no:760, pl:748, pt:708, ro:770, sk:799, es:1056, sv:754, th:753, tr:744, uk:769, vi:774 },
  '9274956467e3e224807498.79791832': { hr:793, cs:765, da:767, nl:737, fr:673, de:666, el:761, id:757, it:734, ko:733, ms:749, no:759, pl:748, pt:708, ro:770, sk:799, es:1056, sv:754, th:753, tr:744, uk:769, vi:774 },
  '50011170688b3050b0a7f8.40995136': { da:767, nl:737, fr:673, de:666, id:757, it:734, ko:733, ms:749, no:760, pl:748, pt:708, ro:770, es:1056, sv:754, th:753, tr:744, uk:769, vi:774 },
  '35679002689c4f3ba6dd50.31739712': { es:1056 },
  '1600517668d38be7f36ba4.51132642': { es:1056 },
  '4780438967fe077b4e6484.83742970': { nl:737, fr:673, de:666, it:734, pt:708, es:1056 },
  '491848986923fad6dc2f85.42477363': { hr:793, cs:765, da:767, nl:737, et:10154, fil:818, fi:768, fr:673, de:666, el:761, hu:773, id:757, it:734, ko:733, lv:10153, lt:10152, ms:749, no:760, pl:748, pt:708, ro:770, sk:799, sl:10159, es:1056, sv:754, th:753, tr:744, uk:769, vi:774 },
  '1274536968b58980dc56a0.78363786': { nl:737, fr:673, de:666, it:734, pt:708, es:1056 }
};

const GUIDES = {
  cs: 'Register: formal 2nd-person plural (vykani). Concise, readable, friendly but authoritative; short clear sentences. Gender-neutral where possible, otherwise grammatical neutral masculine; never he/she dual-gender syntax. Avoid word-for-word translation. Standard Czech grammar, typography, numbers and dates.',
  da: 'Register: informal du. Informal, helpful, engaging yet professional; active voice; clarity over length; avoid noun-heavy formal phrasing. Buttons and CTAs: imperative. Help-centre headlines: infinitive. Body-text instructions: imperative. Cite UI elements capitalised without quotation marks even if the source quotes them. Avoid over-using possessive pronouns.',
  de: 'Register: duzen everywhere including emails and legal text; du/dir/dich/dein lowercase except sentence-initial. Generic masculine, no gender star, colon or Binnen-I. Short sentences. Neue Deutsche Rechtschreibung with the sharp s, not ss. German low-high quotes only. Plain spaces and plain hyphens only. Buttons and labels: infinitive. Full CTA sentences and instructions: du-imperative. No final period on labels, buttons or headings; period on full sentences including error messages. Abonnement in all products. Konto not Account. E-Mail. QR-Code hyphenated. Keep English for Dashboard, Support, Upload, Download.',
  el: 'Register: formal 2nd-person plural always. Buttons and CTAs: translate English infinitives as Greek noun forms, not imperatives. Avoid gendered language; default masculine acceptable if rephrasing fails; never dual-gender syntax. Clear friendly tone, no slang. Split long sentences. Final nu: keep on ton and on den; normal rules for min; remove from autin. Dates DD/MM/YYYY, 24-hour. Decimal comma, currency symbol after the figure.',
  es: 'Register: informal tu. Clear, direct, professional but simple and natural. Buttons: infinitive. Active voice. Prioritise clarity and naturalness over literal translation. Follow RAE and Fundeu.',
  et: 'Register: informal sina. Informal yet professional, helpful, engaging; avoid colloquialisms. Clarity and readability first; rephrase rather than translate literally; active voice. UI elements: capitalise the first letter AND use curly quotes around them. Buttons and CTAs: imperative. Currency: number then non-breaking space then code or symbol. Hyphen for compounds, en dash for numeric ranges. No full stop at the end of headlines. Curly quotation marks low-high. Non-breaking space between number and unit.',
  fi: 'Good standard Finnish; avoid colloquial language. Headings: noun or verb form depending on context. Active voice preferred, straightforward language; avoid overusing politeness words like please. Bulleted full sentences take a capital and a full stop; fragments take a capital and no full stop; fragments continuing the lead-in take lower case, no commas or and/or between items, and a full stop on the last. Curved quotation marks and apostrophes. Non-breaking space between number and unit or percentage. Hyphen for compounds, en dash for ranges. Thousand separator a non-breaking space, decimal comma. Dates 29.11.2022 short, 29. marraskuuta 2022 long.',
  fil: 'Everyday language: friendly, casual, approachable; fun, simple, easy to read. Prefer active sentences (karaniwang ayos) over passive unless the passive is clearer. Inclusive language; Filipino pronouns are non-gendered, so avoid importing gender from the English. Follow the glossary.',
  fr: 'Register: vous unless the source is plainly informal. Clear and concise, never literal; always idiomatic. Exclamation points only occasionally. Aim for gender-neutral epicene phrasing; where addressing the user directly and that fails, add the feminine mark in parentheses. Capitalisation follows French orthography, including the definite-article rule; never carry English title case across. Standard French abbreviations.',
  hr: 'Register: formal 2nd-person plural, Vi capitalised when written out. Buttons and CTAs: nouns where natural but avoid verbal nouns; use imperative verbs instead. Unambiguous prompts to the user take 2nd person plural; prompts the user gives the system may take 2nd person singular. Sentence case. Product names unchanged. Follow pravopis.hr. Rephrase rather than translate word for word.',
  hu: 'Register: informal you (tegezes). Straightforward language: boil the sentence down to its essence and rebuild it as simply as possible. Active voice. Be brief; break up long sentences; drop superfluous words; prefer shorter words. Anglicisms acceptable where widely used, with Hungarian spelling (szelfi not selfie). Always avoid aztozas. Drop the English please, since kerjuk and kerlek are usually unnecessary. Prefer -nak/-nek over szamara, ha over amennyiben, de over azonban, ezert over ennek kovetkezteben, hogy over annak erdekeben hogy. Follow A magyar helyesiras szabalyai.',
  id: 'Register: formal, translate you as Anda at all times, friendly tone. Follow EYD and KBBI. Effective and concise, natural flow. Headings and buttons: noun or verb form following the source style. Decimal comma, thousand period. Dates DD/MM/YYYY, 24-hour clock with a dot separator.',
  it: 'Register: informal tu. Friendly, inclusive, respectful, optimistic. CTAs and buttons: imperative. Avoid long sentences and repetition. Prefer phrasing that works for both genders, else the informato/a form. Never translate URLs. Dates DD/MM/YY, Italian abbreviations. Currency 29,99 with the symbol after. Accented capitals always. High double quotes, period outside the quotes.',
  ko: 'Register: friendly but polite. Declaratives take the -seyo form, questions the -nikka form. Concise. CTA buttons: noun form, not -hagi. Avoid second-person address; where unavoidable use the formal honorific. Sentences end with a period; convert a source colon to a period; no periods in titles or headings. Metric units, no space between number and unit. Dates YYYY/MM/DD, 12-hour clock with Korean AM/PM markers.',
  lt: 'Register: semi-formal, address the reader as jus with lower-case j; friendly conversational tone, short clear sentences, simple words. Translate creatively so it reads as if written in Lithuanian, not translated; vary expression and sentence structure from the English. Buttons: infinitive. Lithuanian low-high quotation marks. Dates 2024-09-10 or 2024 m. rugsejo 10 d., consistently. Decimal comma; currency symbol after the number with a non-breaking space.',
  lv: 'Register: formal jus, NOT capitalised. Avoid over-using pronouns, especially possessives; keep it user-friendly despite the 2nd person plural. Aim for creative translation that reads as an original; rephrase and restructure freely. Titles: substantive or imperative, never followed by a period. Buttons: infinitive. Links: infinitive. Progress messages: indicative. No quotation marks around UI references unless needed for clarity. En dashes, not em dashes. Latvian quotation marks. Dates 01.01.2025 or 2025. gada 1. janvaris. Never use variable gender endings; avoid variable number endings. Decimal comma; ISO currency code after the number with a non-breaking space.',
  ms: 'Register: friendly, not overly formal except in legal contexts; inclusive, respectful, optimistic. Follow DBP references. Pronouns are gender-neutral. Avoid unnecessary plural marking unless context requires it. CTA buttons: imperative verbs without suffixes.',
  nl: 'Register: informal you (jij/je); warm, welcoming, engaging, informal but still professional. Follow Van Dale and Woordenlijst.org. Paraphrasing permitted provided register and meaning hold. CTAs: imperative. Buttons: infinitive.',
  no: 'Register: informal du. Informal, helpful, engaging yet professional; active voice; clarity over length. Buttons and CTAs: imperative. Help-centre headlines: infinitive. Body-text instructions: imperative. Cite UI elements capitalised without quotation marks. Avoid over-using possessive pronouns. Exclamation points and superlatives sparingly.',
  pl: 'Register: 2nd person singular. Gender-neutral forms where possible. Avoid English passive voice; make the actor the subject. Polish low-high quotation marks. En dash, not a hyphen, for ranges. Decimal comma. Ordinals take a period after the number. Do not copy English capitalisation in UI names; sentence case. Exclamation marks sparingly.',
  pt: 'Brazilian Portuguese. Register: formal but friendly, confident, helpful, authoritative. Dates dd/mm/yyyy. 24-hour clock written as 23h30, no spaces, no leading zeros. Space between number and unit; do not pluralise unit symbols. Metric only. Currency R$ 1,10. Decimal comma, thousand period.',
  ro: 'Register: informal tu. Informal, engaging, friendly; active voice. Gender-neutral phrasing. Natural everyday Romanian where appropriate. Buttons and CTAs: direct imperative verbs. Borrowed words take -uri without a hyphen; acronyms and foreign terms with non-standard endings take a hyphen. Check DOOM and DEX.',
  sk: 'Register: formal vy throughout. Capitalise V only in personalised emails, never in general website copy. Space between number and unit; space as thousand separator over four digits; true minus sign for negatives. Currency after the amount. Sentence case always, even where the source uses title case. Accented capitals. Gender-neutral rephrasing.',
  sl: 'Register: vikanje (formal) for the reader, which also avoids bracket-and-slash gender workarounds; never use those. Natural, unforced language: professional and expert yet friendly and warm, occasionally light where context allows, always polite and respectful of readers in all their diversity. Concise: say it short and clear, less is more. Follow the glossary, otherwise established enneagram and personality-analysis terminology. Exception to vikanje: buttons and links that read as commands to the device take the informal imperative (Zacni, Poslji, Tiskaj).',
  sv: 'Register: informal du, never the singular ni. Informal, helpful, engaging yet professional; active voice; clarity over length. Buttons and CTAs: imperative. Help-centre headlines: infinitive. Body-text instructions: imperative. Cite UI elements capitalised without quotation marks. Avoid over-using possessive pronouns. Exclamation points and superlatives sparingly. Gender-neutral vocabulary where available.',
  th: 'Thai per the reviewed guide of 1 Sep 2026. No spaces between words; spaces only where Thai convention requires a phrase break. No sentence-final period. Arabic numerals. Latin script only for brand names and placeholders. Neutral polite register; avoid sentence-final politeness particles in UI copy.',
  tr: 'Register: 2nd person plural polite for body copy and CTA links, but avoid the over-formal -iniz form. Buttons: 2nd person singular. Currency as a code to the right of the figure with a space (10 USD), never a symbol on the left. Turkish decimal and thousand separators. Times use a full stop, not a colon. Follow TDK.',
  uk: 'Register: formal Vy, gender-neutral language. Friendly tone; avoid pronoun-heavy phrasing and repetition. Restructure the English sentence so it reads naturally in Ukrainian. CTAs: imperative. Ordinary buttons: infinitive. Guillemets for quotes, em dash, curly apostrophe. Respect character limits.',
  vi: 'Sentence case in general; exception for widely used organisation names. Avoid passive voice. Double quotes even where the source uses single. No comma before va or hoac. No hyphens splitting words. Decimal comma, thousand full stop. 24-hour clock. No space before a full stop, none inside brackets.'
};

const EXCLUDE_TAGS = ['to_exclude'];
return [{ json: { DRY_RUN, MAX_UNITS_PER_FIRE, MODEL, TM_PAGES, GLOSSARY_PID, PSEUDO, PROJECTS, FAMILY, LANGS, GUIDES, EXCLUDE_TAGS } }];

const c = $('Config').first().json;
const ev = $('Lokalise Event').first().json || {};
const b = ev.body || ev;
const store = $getWorkflowStaticData('global');
if (!store.seen) { store.seen = {}; }

const pid = String(b.project && b.project.id ? b.project.id : (b.project_id || ''));
const type = String(b.event || b.event_type || '');
const project = c.PROJECTS[pid];
const drop = [];
if (!project) { drop.push('project not in scope: ' + pid); }
if (project && project.tm === null) { drop.push('project has no custom translation statuses - blocked'); }

const KEY_EVENTS = ['project.key.added', 'project.keys.added'];
const TRANS_EVENTS = ['project.translation.updated', 'project.translations.updated'];
let ids = [];
if (KEY_EVENTS.indexOf(type) !== -1) {
  const arr = b.keys || (b.key ? [b.key] : []);
  for (const k of arr) { if (k && (k.id || k.key_id)) { ids.push(Number(k.id || k.key_id)); } }
} else if (TRANS_EVENTS.indexOf(type) !== -1) {
  const arr = b.translations || (b.translation ? [b.translation] : []);
  for (const t of arr) {
    const iso = String((t.language && t.language.iso) || t.language_iso || '');
    if (iso !== 'en') { continue; }
    if (t.key && (t.key.id || t.key_id)) { ids.push(Number(t.key.id || t.key_id)); }
    else if (t.key_id) { ids.push(Number(t.key_id)); }
  }
  if (!ids.length) { drop.push('translation event with no EN key ids'); }
} else {
  drop.push('event type not handled: ' + type);
}

const fresh = [];
for (const id of ids) { if (!store.seen[pid + ':' + id]) { fresh.push(id); } }
const capped = fresh.slice(0, c.MAX_UNITS_PER_FIRE);

return [{ json: {
  has_work: capped.length > 0 && !!project && project.tm !== null,
  pid: pid, project_name: project ? project.name : null, event: type,
  key_ids: capped, deferred: fresh.length - capped.length, dropped: drop
} }];

const c = $('Config').first().json;
const w = $('Normalize Event').first().json;
const B = 'https://api.lokalise.com/api2';
const out = [];
out.push({ json: { kind: 'keys', pid: w.pid, url: B + '/projects/' + w.pid + '/keys?filter_key_ids=' + w.key_ids.join(',') + '&include_translations=1&limit=200' } });
out.push({ json: { kind: 'glossary', pid: c.GLOSSARY_PID, url: B + '/projects/' + c.GLOSSARY_PID + '/glossary-terms?limit=500' } });
// TM corpus: firing project plus siblings only, rebuilt every fire but small enough to be cheap.
const fam = c.FAMILY[w.pid] || [w.pid];
for (const p of fam) {
  for (let pg = 1; pg <= c.TM_PAGES; pg++) {
    out.push({ json: { kind: 'tm', pid: p, page: pg, url: B + '/projects/' + p + '/keys?include_translations=1&limit=200&page=' + pg } });
  }
}
return out;

const c = $('Config').first().json;
const w = $('Normalize Event').first().json;
const reqs = $('Build Fetch Plan').all();
const res = $input.all();
const nrm = function (s) { return String(s == null ? '' : s).replace(/\s+/g, ' ').trim().toLowerCase(); };
const txt = function (t) { if (t == null) { return ''; } if (typeof t === 'object') { return ''; } return String(t); };

let targetKeys = null;
const glossary = [];
const tm = {};
const fetchErrors = [];

for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  const r = res[i].json || {};
  const b = r.body || {};
  if (r.statusCode !== 200) { fetchErrors.push(meta.kind + ' ' + meta.pid + ' p' + (meta.page || '-') + ' status ' + r.statusCode); continue; }
  if (meta.kind === 'keys') {
    if (!Array.isArray(b.keys)) { throw new Error('affected-keys fetch returned no array - aborting rather than filling blind'); }
    targetKeys = b.keys;
  } else if (meta.kind === 'glossary') {
    for (const t of (b.data || [])) { if (t.translatable) { glossary.push(t); } }
  } else if (meta.kind === 'tm') {
    if (!Array.isArray(b.keys)) { continue; }
    for (const k of b.keys) {
      if (k.is_archived) { continue; }
      let en = '';
      const per = {};
      for (const t of (k.translations || [])) {
        const s = txt(t.translation);
        if (!s.trim()) { continue; }
        if (t.language_iso === 'en') { en = s; continue; }
        if (t.is_reviewed && !t.is_fuzzy && !t.is_unverified) { per[t.language_iso] = s; }
      }
      if (!en.trim()) { continue; }
      const key = nrm(en);
      if (!tm[key]) { tm[key] = {}; }
      for (const iso of Object.keys(per)) {
        if (tm[key][iso] === undefined) { tm[key][iso] = per[iso]; }
        else if (tm[key][iso] !== per[iso]) { tm[key][iso] = null; }
      }
    }
  }
}
if (targetKeys === null) { throw new Error('affected-keys fetch never returned - aborting'); }

const langs = c.LANGS[w.pid] || {};
const tmHits = [];
const aiUnits = [];
const skipped = [];

for (const k of targetKeys) {
  const name = (k.key_name || {}).web || (k.key_name || {}).other || '';
  if (k.is_archived) { skipped.push({ key: name, why: 'archived' }); continue; }
  if (k.is_hidden) { skipped.push({ key: name, why: 'hidden' }); continue; }
  let excluded = false;
  for (const t of c.EXCLUDE_TAGS) { if ((k.tags || []).indexOf(t) !== -1) { excluded = true; } }
  if (excluded) { skipped.push({ key: name, why: 'tagged to_exclude' }); continue; }
  if (k.is_plural) { skipped.push({ key: name, why: 'plural - not handled' }); continue; }

  let en = '';
  const empty = [];
  for (const t of (k.translations || [])) {
    const s = txt(t.translation);
    if (t.language_iso === 'en') { en = s; continue; }
    if (c.PSEUDO.indexOf(t.language_iso) !== -1) { continue; }   // never AI-fill a pseudo-locale
    if (langs[t.language_iso] === undefined) { continue; }
    if (!s.trim()) { empty.push(t.language_iso); }
  }
  if (!en.trim()) { skipped.push({ key: name, why: 'empty EN source' }); continue; }
  if (!empty.length) { skipped.push({ key: name, why: 'nothing empty' }); continue; }

  const gslice = [];
  for (const g of glossary) {
    let term = '';
    for (const tr of (g.translations || [])) { if (tr.langIso === 'en' || tr.langId === 640) { term = tr.translation; } }
    if (!term) { term = g.term || ''; }
    if (!term) { continue; }
    if (nrm(en).indexOf(nrm(term)) === -1) { continue; }
    gslice.push(g);
  }
  const hit = tm[nrm(en)] || {};

  for (const iso of empty) {
    if (hit[iso]) {
      tmHits.push({ key_id: k.key_id, key: name, iso: iso, lang_id: langs[iso], text: hit[iso] });
    } else {
      const terms = [];
      for (const g of gslice) {
        for (const tr of (g.translations || [])) { if (tr.langIso === iso && tr.translation) { terms.push((g.term || '') + ' = ' + tr.translation); } }
      }
      aiUnits.push({ key_id: k.key_id, key: name, iso: iso, lang_id: langs[iso], en: en,
        guide: c.GUIDES[iso] || '', glossary: terms.slice(0, 25), description: k.description || '', char_limit: k.char_limit || 0 });
    }
  }
}
return [{ json: { pid: w.pid, project_name: w.project_name, tm_hits: tmHits, ai_units: aiUnits,
  skipped: skipped, fetch_errors: fetchErrors, tm_index_size: Object.keys(tm).length, deferred: w.deferred } }];

const c = $('Config').first().json;
const p = $('Plan Units').first().json;
const out = [];
for (const u of p.ai_units) {
  const sys = 'You are a professional localisation translator working into ' + u.iso + '. Translate the English UI string exactly, obeying the style guide. Output ONLY the translation, no quotes, no commentary. Preserve every placeholder, HTML tag and attribute unchanged, including surrounding spaces and punctuation. Never translate placeholder names or brand names. Preserve leading and trailing whitespace exactly. Match the source terminal punctuation.';
  let usr = 'STYLE GUIDE for ' + u.iso + ':\n' + u.guide + '\n\n';
  if (u.glossary.length) { usr += 'GLOSSARY - mandatory, overrides the style guide:\n' + u.glossary.join('\n') + '\n\n'; }
  if (u.description) { usr += 'CONTEXT: ' + u.description + '\n\n'; }
  if (u.char_limit) { usr += 'HARD CHARACTER LIMIT: ' + u.char_limit + '\n\n'; }
  usr += 'KEY NAME (context only, do not translate): ' + u.key + '\n\nENGLISH SOURCE:\n' + u.en;
  out.push({ json: { unit: u, body: { model: c.MODEL, max_tokens: 1000, temperature: 0.2,
    messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ] } } });
}
if (!out.length) { return [{ json: { unit: null, body: { model: c.MODEL, max_tokens: 5, messages: [ { role: 'user', content: 'ok' } ] }, nothing_to_generate: true } }]; }
return out;

const c = $('Config').first().json;
const p = $('Plan Units').first().json;
const reqs = $('Build AI Requests').all();
const res = $input.all();
const proj = c.PROJECTS[p.pid];
const rejected = [];
const accepted = [];
const LATIN = /[A-Za-z]/;
const stripQ = function (s) { return s.replace(/["\u201c\u201d\u00ab\u00bb\u201e\u2018\u2019']+$/, ''); };
const endPunct = function (s) { const t = stripQ(s.trim()); const ch = t.slice(-1); return /[.!?:;]/.test(ch) ? ch : ''; };
const tags = function (s) { const m = String(s).match(/<[^>]+>/g) || []; return m.slice().sort().join('|'); };
const phold = function (s) { const m = String(s).match(/\[%[^\]]+\]|\{\{?[^}]+\}?\}|%[sd@]|%\d+\$[sd@]/g) || []; return m.slice().sort().join('|'); };

for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  if (!meta || !meta.unit) { continue; }
  const u = meta.unit;
  const r = res[i].json || {};
  if (r.statusCode !== 200) { rejected.push({ key: u.key, iso: u.iso, why: 'model HTTP ' + r.statusCode }); continue; }
  let outText = '';
  try { outText = (r.body || {}).choices[0].message.content; } catch (e) { outText = ''; }
