  if (excluded) { skipped.push({ key: name, why: 'tagged to_exclude' }); continue; }
  if (k.is_plural) { skipped.push({ key: name, why: 'plural - not handled' }); continue; }

  let en = '';
  const empty = [];
  for (const t of (k.translations || [])) {
    const s = txt(t.translation);
    if (t.language_iso === 'en') { en = s; continue; }
    if (c.PSEUDO.indexOf(t.language_iso) !== -1) { continue; }   // never AI-fill a pseudo-locale
    if (langs[t.language_iso] === undefined) { continue; }
    if (!s.trim()) { empty.push(t.language_iso); }
  }
  if (!en.trim()) { skipped.push({ key: name, why: 'empty EN source' }); continue; }
  if (!empty.length) { skipped.push({ key: name, why: 'nothing empty' }); continue; }

  const gslice = [];
  for (const g of glossary) {
    let term = '';
    for (const tr of (g.translations || [])) { if (tr.langIso === 'en' || tr.langId === 640) { term = tr.translation; } }
    if (!term) { term = g.term || ''; }
    if (!term) { continue; }
    if (nrm(en).indexOf(nrm(term)) === -1) { continue; }
    gslice.push(g);
  }
  const hit = tm[nrm(en)] || {};

  for (const iso of empty) {
    if (hit[iso]) {
      tmHits.push({ key_id: k.key_id, key: name, iso: iso, lang_id: langs[iso], text: hit[iso] });
    } else {
      const terms = [];
      for (const g of gslice) {
        for (const tr of (g.translations || [])) { if (tr.langIso === iso && tr.translation) { terms.push((g.term || '') + ' = ' + tr.translation); } }
      }
      aiUnits.push({ key_id: k.key_id, key: name, iso: iso, lang_id: langs[iso], en: en,
        guide: c.GUIDES[iso] || '', glossary: terms.slice(0, 25), description: k.description || '', char_limit: k.char_limit || 0 });
    }
  }
}
return [{ json: { pid: w.pid, project_name: w.project_name, tm_hits: tmHits, ai_units: aiUnits,
  skipped: skipped, fetch_errors: fetchErrors, tm_index_size: Object.keys(tm).length, deferred: w.deferred } }];

const c = $('Config').first().json;
const p = $('Plan Units').first().json;
const out = [];
for (const u of p.ai_units) {
  const sys = 'You are a professional localisation translator working into ' + u.iso + '. Translate the English UI string exactly, obeying the style guide. Output ONLY the translation, no quotes, no commentary. Preserve every placeholder, HTML tag and attribute unchanged, including surrounding spaces and punctuation. Never translate placeholder names or brand names. Preserve leading and trailing whitespace exactly. Match the source terminal punctuation.';
  let usr = 'STYLE GUIDE for ' + u.iso + ':\n' + u.guide + '\n\n';
  if (u.glossary.length) { usr += 'GLOSSARY - mandatory, overrides the style guide:\n' + u.glossary.join('\n') + '\n\n'; }
  if (u.description) { usr += 'CONTEXT: ' + u.description + '\n\n'; }
  if (u.char_limit) { usr += 'HARD CHARACTER LIMIT: ' + u.char_limit + '\n\n'; }
  usr += 'KEY NAME (context only, do not translate): ' + u.key + '\n\nENGLISH SOURCE:\n' + u.en;
  out.push({ json: { unit: u, body: { model: c.MODEL, max_tokens: 1000, temperature: 0.2,
    messages: [ { role: 'system', content: sys }, { role: 'user', content: usr } ] } } });
}
if (!out.length) { return [{ json: { unit: null, body: { model: c.MODEL, max_tokens: 5, messages: [ { role: 'user', content: 'ok' } ] }, nothing_to_generate: true } }]; }
return out;

const c = $('Config').first().json;
const p = $('Plan Units').first().json;
const reqs = $('Build AI Requests').all();
const res = $input.all();
const proj = c.PROJECTS[p.pid];
const rejected = [];
const accepted = [];
const LATIN = /[A-Za-z]/;
const stripQ = function (s) { return s.replace(/["\u201c\u201d\u00ab\u00bb\u201e\u2018\u2019']+$/, ''); };
const endPunct = function (s) { const t = stripQ(s.trim()); const ch = t.slice(-1); return /[.!?:;]/.test(ch) ? ch : ''; };
const tags = function (s) { const m = String(s).match(/<[^>]+>/g) || []; return m.slice().sort().join('|'); };
const phold = function (s) { const m = String(s).match(/\[%[^\]]+\]|\{\{?[^}]+\}?\}|%[sd@]|%\d+\$[sd@]/g) || []; return m.slice().sort().join('|'); };

for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  if (!meta || !meta.unit) { continue; }
  const u = meta.unit;
  const r = res[i].json || {};
  if (r.statusCode !== 200) { rejected.push({ key: u.key, iso: u.iso, why: 'model HTTP ' + r.statusCode }); continue; }
  let outText = '';
  try { outText = (r.body || {}).choices[0].message.content; } catch (e) { outText = ''; }
  if (!outText || !String(outText).trim()) { rejected.push({ key: u.key, iso: u.iso, why: 'empty model output' }); continue; }
  let t = String(outText);
  if (/^".*"$/.test(t.trim()) && !/^".*"$/.test(u.en.trim())) { t = t.trim().slice(1, -1); }
  const lead = (u.en.match(/^\s*/) || [''])[0];
  const trail = (u.en.match(/\s*$/) || [''])[0];
  t = lead + t.trim() + trail;
  if (tags(t) !== tags(u.en)) { rejected.push({ key: u.key, iso: u.iso, why: 'HTML tag signature changed' }); continue; }
  if (phold(t) !== phold(u.en)) { rejected.push({ key: u.key, iso: u.iso, why: 'placeholder signature changed' }); continue; }
  const multi = u.en.trim().split(/\s+/).length > 1;
  if (multi && t.trim().toLowerCase() === u.en.trim().toLowerCase()) { rejected.push({ key: u.key, iso: u.iso, why: 'model returned the source unchanged' }); continue; }
  if (u.iso === 'th' && LATIN.test(t.replace(/<[^>]+>/g, '').replace(/\[%[^\]]+\]/g, ''))) { rejected.push({ key: u.key, iso: u.iso, why: 'Latin script in Thai output' }); continue; }
  if (u.iso !== 'th' && endPunct(t) !== endPunct(u.en)) { rejected.push({ key: u.key, iso: u.iso, why: 'terminal punctuation differs' }); continue; }
  if (u.char_limit && t.length > u.char_limit) { rejected.push({ key: u.key, iso: u.iso, why: 'over char limit' }); continue; }
  accepted.push({ key_id: u.key_id, key: u.key, iso: u.iso, text: t, kind: 'ai' });
}
for (const h of p.tm_hits) { accepted.push({ key_id: h.key_id, key: h.key, iso: h.iso, text: h.text, kind: 'tm' }); }

// bulk PUT /keys keeps ONE translations array per key_id - all locales must be grouped
const byKey = {};
for (const a of accepted) {
  if (!byKey[a.key_id]) { byKey[a.key_id] = []; }
  byKey[a.key_id].push({ language_iso: a.iso, translation: a.text, is_fuzzy: a.kind === 'ai',
    is_reviewed: false, custom_translation_status_ids: [ a.kind === 'tm' ? proj.tm : proj.ai ] });
}
const keys = [];
for (const kid of Object.keys(byKey)) { keys.push({ key_id: Number(kid), translations: byKey[kid] }); }
const tmCount = accepted.filter(function (a) { return a.kind === 'tm'; }).length;

return [{ json: { pid: p.pid, project_name: p.project_name, dry_run: c.DRY_RUN,
  url: 'https://api.lokalise.com/api2/projects/' + p.pid + '/keys', payload: { keys: keys },
  will_write: keys.length > 0 && !c.DRY_RUN,
  counts: { tm: tmCount, ai: accepted.length - tmCount, keys: keys.length, rejected: rejected.length, skipped: p.skipped.length },
  rejected: rejected, skipped: p.skipped, accepted: accepted,
  fetch_errors: p.fetch_errors, tm_index_size: p.tm_index_size, deferred: p.deferred } }];

const g = $('Gate And Group').first().json;
const r = $input.first().json || {};
const store = $getWorkflowStaticData('global');
if (!store.seen) { store.seen = {}; }
const confirmed = [];
const mismatched = [];
if (g.will_write && r.statusCode === 200) {
  const back = {};
  for (const k of ((r.body || {}).keys || [])) {
    for (const t of (k.translations || [])) { back[k.key_id + ':' + t.language_iso] = t.translation; }
  }
  for (const a of g.accepted) {
    if (back[a.key_id + ':' + a.iso] === a.text) { confirmed.push(a.key + ' [' + a.iso + ']'); store.seen[g.pid + ':' + a.key_id] = Date.now(); }
    else { mismatched.push({ key: a.key, iso: a.iso, sent: a.text, echoed: back[a.key_id + ':' + a.iso] === undefined ? '(absent)' : back[a.key_id + ':' + a.iso] }); }
  }
}
return [{ json: { project: g.project_name, dry_run: g.dry_run, wrote: !!g.will_write,
  http: r.statusCode === undefined ? null : r.statusCode, counts: g.counts,
  confirmed: confirmed.length, confirmed_list: confirmed.slice(0, 40), mismatched: mismatched,
  rejected: g.rejected, skipped: g.skipped, fetch_errors: g.fetch_errors,
  tm_index_size: g.tm_index_size, deferred_to_next_fire: g.deferred,
  rollback_hint: 'to revert, set the listed key/locale pairs back to empty string' } }];
